import{_ as i,c as s,o as t,ag as n}from"./chunks/framework.Ci10AEOF.js";const a="/docs-website/assets/extensions.CdrJQyds.png",u=JSON.parse('{"title":"OIE Plugin Guide","description":"","frontmatter":{},"headers":[],"relativePath":"engine/plugins.md","filePath":"engine/plugins.md","lastUpdated":1793057853000}'),o={name:"engine/plugins.md"};function l(r,e,d,h,p,c){return t(),s("div",null,e[0]||(e[0]=[n('<h1 id="oie-plugin-guide" tabindex="-1">OIE Plugin Guide <a class="header-anchor" href="#oie-plugin-guide" aria-label="Permalink to &quot;OIE Plugin Guide&quot;">​</a></h1><p>Plugins add connectors, data types, filter and transformer steps, and Administrator screens to Open Integration Engine (OIE). Resources for developing plugins are under <a href="#developing-extensions">Developing extensions</a>.</p><h2 id="accessing-the-extensions-plugins-section" tabindex="-1">Accessing the extensions/plugins section <a class="header-anchor" href="#accessing-the-extensions-plugins-section" aria-label="Permalink to &quot;Accessing the extensions/plugins section&quot;">​</a></h2><p>To manage plugins in Open Integration Engine:</p><ol><li>Launch and log in to the <strong>OIE Administrator Client</strong></li><li>Select <strong>Extensions</strong> from the <strong>Engine</strong> sidebar menu</li><li>You will see a list of all installed plugins along with their status and other details.</li></ol><p><img src="'+a+`" alt="The Extensions view listing installed connectors and plugins, with the Install Extension from File System field at the bottom"></p><p>This screen installs, enables, disables and uninstalls extensions. It is not where an extension is configured. A plugin that ships a settings panel adds its own tab under <strong>Engine</strong> &gt; <strong>Settings</strong>, named by the plugin, and that is where its configuration lives.</p><p>Most of what looks like core functionality is an extension, loaded the same way as a third-party plugin: the connectors, the data types, the filter and transformer steps, the attachment viewers, and MLLP framing all ship as extensions and appear in this list.</p><p>Community extensions are cataloged at <a href="https://openintegrationengine.org/plugins/" target="_blank" rel="noreferrer">openintegrationengine.org/plugins</a>.</p><h2 id="installing-plugins" tabindex="-1">Installing plugins <a class="header-anchor" href="#installing-plugins" aria-label="Permalink to &quot;Installing plugins&quot;">​</a></h2><h3 id="installing-via-the-administrator-ui" tabindex="-1">Installing via the Administrator UI <a class="header-anchor" href="#installing-via-the-administrator-ui" aria-label="Permalink to &quot;Installing via the Administrator UI&quot;">​</a></h3><p>To install a plugin through the Administrator:</p><ol><li>Download the plugin <code>.zip</code> file from a trusted source</li><li>Launch and log in to the <strong>OIE Administrator Client</strong></li><li>Select <strong>Extensions</strong> from the <strong>Engine</strong> sidebar menu</li><li>Click the <strong>Browse</strong> button</li><li>Locate and select the plugin <code>.zip</code> file</li><li>Click <strong>Open</strong></li><li>Click <strong>Install</strong></li><li><strong>Restart</strong> the OIE Server and the Administrator for the plugin to take effect</li></ol><h3 id="manual-installation" tabindex="-1">Manual installation <a class="header-anchor" href="#manual-installation" aria-label="Permalink to &quot;Manual installation&quot;">​</a></h3><p>For environments where UI-based installation is not feasible, you can install plugins manually:</p><ol><li>Stop the OIE Server</li><li>Extract the plugin <code>.zip</code> file</li><li>Copy the extracted plugin folder to the <code>extensions/</code> directory in your OIE installation. In these samples <code>/opt/oie</code> and <code>C:\\Program Files\\OIE</code> stand for wherever OIE is installed:<div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-qTLCe" id="tab-35WoYt3" checked><label data-title="Linux/macOS" for="tab-35WoYt3">Linux/macOS</label><input type="radio" name="group-qTLCe" id="tab-V3GSnnV"><label data-title="Windows" for="tab-V3GSnnV">Windows</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie/extensions/</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Copy-Item</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Recurse my</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plugin </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:\\Program Files\\OIE\\extensions\\&quot;</span></span></code></pre></div></div></div></li><li><strong>(Linux/macOS only)</strong> Ensure proper file permissions so the OIE process can read the plugin files. The plugin files should be owned by the same user that runs OIE:<div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-lHggB" id="tab-CM48ISt" checked><label data-title="Linux/macOS" for="tab-CM48ISt">Linux/macOS</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Replace &#39;oie&#39; with the user account that runs the OIE Server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oie:oie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie/extensions/my-plugin</span></span></code></pre></div></div></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>OIE does not create a dedicated system user during installation. It runs as the user who starts the service. Check which user owns your OIE installation directory or runs the OIE process.</p></div></li><li>Start the OIE Server</li></ol><h3 id="installing-in-the-oie-docker-container" tabindex="-1">Installing in the OIE Docker container <a class="header-anchor" href="#installing-in-the-oie-docker-container" aria-label="Permalink to &quot;Installing in the OIE Docker container&quot;">​</a></h3><p>The <code>openintegrationengine/engine:latest</code> image on Docker Hub runs Open Integration Engine 4.5.2, a technology preview, not 4.7.0. No 4.6.0 or 4.7.0 image is published.</p><p>A plugin can be installed in a Docker container in three ways:</p><h4 id="example-1-docker-cli-with-custom-extensions-volume-mount" tabindex="-1">Example 1: Docker CLI with <code>custom-extensions</code> volume mount <a class="header-anchor" href="#example-1-docker-cli-with-custom-extensions-volume-mount" aria-label="Permalink to &quot;Example 1: Docker CLI with \`custom-extensions\` volume mount&quot;">​</a></h4><p>Mount a host directory containing plugin zip files to the container&#39;s <code>custom-extensions</code> directory. The container&#39;s entrypoint script will unzip and install them to the <code>extensions</code> directory prior to launching the server. The Administrator connects on port 8443:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8443:8443</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/local/custom-extensions:/opt/engine/custom-extensions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  openintegrationengine/engine:latest</span></span></code></pre></div><p>Before it starts the server, the entrypoint prints <code>Found N custom extensions.</code>, with N the number of zip files, but only when it found at least one. If <code>docker logs</code> on the container shows no such line, the mounted directory held no <code>.zip</code> files.</p><h4 id="example-2-custom-dockerfile-with-manual-installation" tabindex="-1">Example 2: Custom Dockerfile with manual installation <a class="header-anchor" href="#example-2-custom-dockerfile-with-manual-installation" aria-label="Permalink to &quot;Example 2: Custom Dockerfile with manual installation&quot;">​</a></h4><p>Extract the plugin <code>.zip</code> file on the build host and copy the folder into the image&#39;s <code>extensions/</code> directory. The base image runs as the <code>engine</code> user and owns everything under <code>/opt/engine</code>, so the copied files are given to the same user:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-KxIgi" id="tab-ehMozyX" checked><label data-title="Dockerfile" for="tab-ehMozyX">Dockerfile</label></div><div class="blocks"><div class="language-dockerfile vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> openintegrationengine/engine:latest</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --chown=engine:engine my-plugin/ /opt/engine/extensions/my-plugin/</span></span></code></pre></div></div></div><p>Build and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oie-with-plugins</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8443:8443</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oie-with-plugins</span></span></code></pre></div><h4 id="example-3-docker-compose-with-extensions-download-url" tabindex="-1">Example 3: Docker Compose with <code>EXTENSIONS_DOWNLOAD</code> URL <a class="header-anchor" href="#example-3-docker-compose-with-extensions-download-url" aria-label="Permalink to &quot;Example 3: Docker Compose with \`EXTENSIONS_DOWNLOAD\` URL&quot;">​</a></h4><p>The container supports downloading a bundle of extensions from a remote web server and installing them prior to launching the server. The bundle file is a zip file that contains one or more extension zip files to be installed. The extension zips must sit at the top level of the bundle; the entrypoint only unzips <code>*.zip</code> files directly inside the extracted bundle, and zips nested in a folder are ignored:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-DpQHk" id="tab-hXO8NHs" checked><label data-title="compose.yaml" for="tab-hXO8NHs">compose.yaml</label></div><div class="blocks"><div class="language-yaml vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  oie</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openintegrationengine/engine:latest</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EXTENSIONS_DOWNLOAD=https://my-bucket.s3.us-east-1.amazonaws.com/my-oie-extensions-bundle.zip</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;8080:8080&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;8443:8443&quot;</span></span></code></pre></div></div></div><p>A failed download is not fatal. The entrypoint prints <code>problem with extensions download</code> and starts the server with no extensions installed, so check <code>docker logs</code> for that line when the extensions are missing.</p><h2 id="uninstalling-plugins" tabindex="-1">Uninstalling plugins <a class="header-anchor" href="#uninstalling-plugins" aria-label="Permalink to &quot;Uninstalling plugins&quot;">​</a></h2><h3 id="via-the-administrator-ui" tabindex="-1">Via the Administrator UI <a class="header-anchor" href="#via-the-administrator-ui" aria-label="Permalink to &quot;Via the Administrator UI&quot;">​</a></h3><ol><li>Select <strong>Extensions</strong> from the <strong>Engine</strong> sidebar menu</li><li>Select the extension you want to remove in the <strong>Installed Connectors</strong> or <strong>Installed Plugins</strong> table</li><li>Select <strong>Uninstall Extension</strong> from the <strong>Extension Tasks</strong> menu</li><li>Confirm the uninstallation when prompted</li><li><strong>Restart</strong> the OIE Server and the Administrator</li></ol><h3 id="manual-uninstallation" tabindex="-1">Manual uninstallation <a class="header-anchor" href="#manual-uninstallation" aria-label="Permalink to &quot;Manual uninstallation&quot;">​</a></h3><ol><li>Stop the OIE Server</li><li>Navigate to the <code>extensions/</code> directory</li><li>Remove the plugin folder:<div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-sgDrl" id="tab-Y6_iMFJ" checked><label data-title="Linux/macOS" for="tab-Y6_iMFJ">Linux/macOS</label><input type="radio" name="group-sgDrl" id="tab-28KoTJb"><label data-title="Windows" for="tab-28KoTJb">Windows</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie/extensions/my-plugin</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Remove-Item</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Recurse </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:\\Program Files\\OIE\\extensions\\my-plugin&quot;</span></span></code></pre></div></div></div></li><li>Start the OIE Server</li></ol><p>Deleting the folder removes the code only. <strong>Uninstall Extension</strong> in the Administrator also queues removal of the extension&#39;s saved properties and any database uninstall statements the plugin supplies, and the server applies both at the next start.</p><h2 id="enabling-and-disabling-plugins" tabindex="-1">Enabling and disabling plugins <a class="header-anchor" href="#enabling-and-disabling-plugins" aria-label="Permalink to &quot;Enabling and disabling plugins&quot;">​</a></h2><p>You can temporarily disable plugins without uninstalling them:</p><h3 id="to-disable-a-plugin" tabindex="-1">To disable a plugin <a class="header-anchor" href="#to-disable-a-plugin" aria-label="Permalink to &quot;To disable a plugin&quot;">​</a></h3><ol><li>Select <strong>Extensions</strong> from the <strong>Engine</strong> sidebar menu</li><li>Select the extension in the <strong>Installed Connectors</strong> or <strong>Installed Plugins</strong> table</li><li>Select <strong>Disable Extension</strong> from the <strong>Extension Tasks</strong> menu</li><li><strong>Restart</strong> the OIE Server and the Administrator</li></ol><h3 id="to-enable-a-plugin" tabindex="-1">To enable a plugin <a class="header-anchor" href="#to-enable-a-plugin" aria-label="Permalink to &quot;To enable a plugin&quot;">​</a></h3><ol><li>Select <strong>Extensions</strong> from the <strong>Engine</strong> sidebar menu</li><li>Select the disabled extension in the <strong>Installed Connectors</strong> or <strong>Installed Plugins</strong> table</li><li>Select <strong>Enable Extension</strong> from the <strong>Extension Tasks</strong> menu</li><li><strong>Restart</strong> the OIE Server and the Administrator</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you suspect a plugin is causing issues, disable it and restart the server to confirm.</p></div><h2 id="plugin-compatibility-and-version-requirements" tabindex="-1">Plugin compatibility and version requirements <a class="header-anchor" href="#plugin-compatibility-and-version-requirements" aria-label="Permalink to &quot;Plugin compatibility and version requirements&quot;">​</a></h2><h3 id="checking-compatibility" tabindex="-1">Checking compatibility <a class="header-anchor" href="#checking-compatibility" aria-label="Permalink to &quot;Checking compatibility&quot;">​</a></h3><p>Before installing a plugin, verify:</p><ol><li><strong>OIE Version</strong>: Check the plugin documentation for supported OIE versions</li><li><strong>Java Version</strong>: Some plugins may require specific Java versions</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A plugin declares the server versions it supports in <code>&lt;mirthVersion&gt;</code>, as a comma-separated list of exact versions. A version range is not supported. On OIE 4.7.0 the list must include <code>4.7.0</code>: a plugin built only for 4.6.0 is refused at install, and one already in <code>extensions/</code> is not loaded at startup, which <code>logs/mirth.log</code> reports as <code>is not compatible with this version</code>.</p></div><h2 id="troubleshooting-common-issues" tabindex="-1">Troubleshooting common issues <a class="header-anchor" href="#troubleshooting-common-issues" aria-label="Permalink to &quot;Troubleshooting common issues&quot;">​</a></h2><h3 id="plugin-not-appearing-after-installation" tabindex="-1">Plugin not appearing after installation <a class="header-anchor" href="#plugin-not-appearing-after-installation" aria-label="Permalink to &quot;Plugin not appearing after installation&quot;">​</a></h3><p><strong>Possible causes and solutions:</strong></p><ol><li><strong>Server or Administrator not restarted</strong>: Restart both after installation</li><li><strong>Incorrect directory</strong>: Verify the plugin is in the correct <code>extensions/</code> folder</li><li><strong>File permissions</strong>: Ensure the OIE process has read access to the plugin files</li><li><strong>Corrupted archive</strong>: Re-download and reinstall the plugin</li></ol><h3 id="plugin-causing-server-startup-failures" tabindex="-1">Plugin causing server startup failures <a class="header-anchor" href="#plugin-causing-server-startup-failures" aria-label="Permalink to &quot;Plugin causing server startup failures&quot;">​</a></h3><p>If the server fails to start after installing a plugin:</p><ol><li>Check the server log in <code>logs/mirth.log</code> for error messages</li><li>Try starting the server with the plugin disabled:<div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-2xubU" id="tab-rjZAQHT" checked><label data-title="Linux/macOS" for="tab-rjZAQHT">Linux/macOS</label><input type="radio" name="group-2xubU" id="tab-_6VpJOl"><label data-title="Windows" for="tab-_6VpJOl">Windows</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Move the plugin out of extensions; the server loads only folders inside it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie/extensions/problem-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/oie/</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Move the plugin out of extensions; the server loads only folders inside it</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Move-Item</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;C:\\Program Files\\OIE\\extensions\\problem-plugin&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;C:\\Program Files\\OIE\\&quot;</span></span></code></pre></div></div></div></li><li>If the server then starts, the plugin caused the failure</li></ol><h3 id="plugin-features-not-working" tabindex="-1">Plugin features not working <a class="header-anchor" href="#plugin-features-not-working" aria-label="Permalink to &quot;Plugin features not working&quot;">​</a></h3><ol><li>Verify the extension shows <strong>Enabled</strong> in the <strong>Status</strong> column under <strong>Engine</strong> &gt; <strong>Extensions</strong></li><li>Review server logs for runtime errors</li><li>Check <code>logs/mirth.log</code> for <code>could not locate library</code>, which the server logs at startup for each server or shared library that an enabled, compatible extension declares but does not ship. Client libraries are not checked</li></ol><h3 id="common-error-messages" tabindex="-1">Common error messages <a class="header-anchor" href="#common-error-messages" aria-label="Permalink to &quot;Common error messages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Solution</th></tr></thead><tbody><tr><td><code>ClassNotFoundException</code></td><td>A library the plugin declares in its metadata is missing from its folder</td><td>Look for <code>could not locate library</code> in <code>logs/mirth.log</code> and restore the file it names</td></tr><tr><td><code>NoSuchMethodError</code></td><td>The plugin was built against a different version of a class than the engine ships</td><td>Install a build of the plugin for this engine version</td></tr></tbody></table><h2 id="developing-extensions" tabindex="-1">Developing extensions <a class="header-anchor" href="#developing-extensions" aria-label="Permalink to &quot;Developing extensions&quot;">​</a></h2><h3 id="extension-directory-structure" tabindex="-1">Extension directory structure <a class="header-anchor" href="#extension-directory-structure" aria-label="Permalink to &quot;Extension directory structure&quot;">​</a></h3><p>Each extension lives in its own subdirectory under <code>OIE_HOME/extensions/</code>. Connectors describe themselves with <code>source.xml</code>, <code>destination.xml</code>, or both, depending on which sides they provide, while plugins and data types use <code>plugin.xml</code>. A connector folder can carry a <code>plugin.xml</code> as well, as the TCP connectors do for the service plugin they need.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extensions/</span></span>
<span class="line"><span>├── http/                         # Connector example</span></span>
<span class="line"><span>│   ├── http-server.jar           # Server-side classes</span></span>
<span class="line"><span>│   ├── http-client.jar           # Client-side classes (downloaded to the Administrator)</span></span>
<span class="line"><span>│   ├── http-shared.jar           # Shared classes (loaded on both sides)</span></span>
<span class="line"><span>│   ├── source.xml                # Source connector metadata</span></span>
<span class="line"><span>│   └── destination.xml           # Destination connector metadata</span></span>
<span class="line"><span>└── datapruner/                   # Plugin example</span></span>
<span class="line"><span>    ├── datapruner-server.jar</span></span>
<span class="line"><span>    ├── datapruner-client.jar</span></span>
<span class="line"><span>    ├── datapruner-shared.jar</span></span>
<span class="line"><span>    └── plugin.xml                # Plugin metadata descriptor</span></span></code></pre></div><p>Some extensions also carry a <code>lib/</code> subdirectory for third-party dependencies. Client-only extensions, such as the Mapper and Rule Builder steps, ship no server jar at all.</p><h3 id="extension-metadata" tabindex="-1">Extension metadata <a class="header-anchor" href="#extension-metadata" aria-label="Permalink to &quot;Extension metadata&quot;">​</a></h3><p>A metadata descriptor declares:</p><ul><li>Extension name, author, and version</li><li>Server-side and client-side class names</li><li>Library JAR paths and their type (server, client, or shared)</li><li>API provider classes, meaning servlet interfaces and their implementations</li></ul><h3 id="server-side-extension-points" tabindex="-1">Server-side extension points <a class="header-anchor" href="#server-side-extension-points" aria-label="Permalink to &quot;Server-side extension points&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Extension Type</th><th>Class/Interface</th></tr></thead><tbody><tr><td><strong>Server Plugin</strong></td><td><code>ServerPlugin</code> (interface)</td></tr><tr><td><strong>Service Plugin</strong></td><td><code>ServicePlugin</code> (interface, extends ServerPlugin)</td></tr><tr><td><strong>Channel Plugin</strong></td><td><code>ChannelPlugin</code> (interface, extends ServerPlugin)</td></tr><tr><td><strong>Data Type</strong></td><td><code>DataTypeServerPlugin</code> (abstract class)</td></tr><tr><td><strong>Resource Plugin</strong></td><td><code>ResourcePlugin</code> (interface, extends ServerPlugin)</td></tr><tr><td><strong>Library Plugin</strong></td><td><code>LibraryPlugin</code> (interface, extends ResourcePlugin)</td></tr><tr><td><strong>Authorization Plugin</strong></td><td><code>AuthorizationPlugin</code> (interface, extends ServerPlugin)</td></tr><tr><td><strong>Transmission Mode</strong></td><td><code>TransmissionModeProvider</code> (abstract class, implements ServerPlugin)</td></tr><tr><td><strong>Code Template Plugin</strong></td><td><code>CodeTemplateServerPlugin</code> (interface, extends ServerPlugin)</td></tr><tr><td><strong>Multi-Factor Auth Plugin</strong></td><td><code>MultiFactorAuthenticationPlugin</code> (abstract class, implements ServicePlugin)</td></tr></tbody></table><p>All ten live in <code>com.mirth.connect.plugins</code>.</p><h3 id="building-an-extension" tabindex="-1">Building an extension <a class="header-anchor" href="#building-an-extension" aria-label="Permalink to &quot;Building an extension&quot;">​</a></h3><ol><li>Produce the server-side, client-side, or shared JARs the extension needs</li><li>Write the metadata descriptor (<code>plugin.xml</code>, or <code>source.xml</code> and <code>destination.xml</code> for connectors)</li><li>Package it into the extension directory layout</li><li>Test against a running OIE instance</li></ol><p>An extension&#39;s server half works the same for the <a href="./desktop_administrator.html">Desktop Administrator</a> and the <a href="./web_administrator.html">Web Administrator</a>. Its Swing client classes do not run in the Web Administrator. To give an extension a browser interface, build a web half against the REST endpoints the extension already exposes and put it in a <code>webadmin/</code> folder inside the same extension zip. OIE 4.7.0 does not serve that folder itself; the <a href="https://github.com/gibson9583/oie-web-support-plugin" target="_blank" rel="noreferrer">Web Support</a> extension does. The web extension points, the manifest format and the build are documented in <a href="https://github.com/gibson9583/oie-web-client/blob/main/web-administrator/PLUGINS.md" target="_blank" rel="noreferrer">PLUGINS.md</a> in the web client repository.</p><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h3><ul><li><strong>Plugin Author&#39;s Guide</strong>: <a href="https://github.com/kpalang/mirth-plugin-guide" target="_blank" rel="noreferrer">mirth-plugin-guide</a> - An unofficial collection of tips and tricks for Mirth Connect plugins. Several sections are marked &quot;To be fleshed out&quot;. It does not mention OIE or BridgeLink.</li><li><strong>Sample Plugin</strong>: <a href="https://github.com/kpalang/mirth-sample-plugin" target="_blank" rel="noreferrer">mirth-sample-plugin</a> - A sample plugin project for NextGen Connect, built against Mirth 4.5.0, best used as a template. It does not mention OIE or BridgeLink.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./contributing.html">Contributing to Open Integration Engine</a></li><li><a href="https://hub.docker.com/u/openintegrationengine" target="_blank" rel="noreferrer">OIE Docker Hub</a></li><li><a href="https://github.com/OpenIntegrationEngine/engine" target="_blank" rel="noreferrer">OIE GitHub Repository</a></li></ul>`,79)]))}const k=i(o,[["render",l]]);export{u as __pageData,k as default};
